 static class TestAdapter implements IntegrationOrderAdapter {
  final JdbcTemplate db;volatile String mode="TEST_ACCEPTED",blockKey;volatile CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);
  final ConcurrentHashMap<String,Integer> submitsByKey=new ConcurrentHashMap<>();
  final java.util.concurrent.atomic.AtomicInteger queryCalls=new java.util.concurrent.atomic.AtomicInteger(),submitCalls=new java.util.concurrent.atomic.AtomicInteger();
  TestAdapter(JdbcTemplate db){this.db=db;}
  SyntheticOrderAdapter delegate(){var env=new org.springframework.core.env.StandardEnvironment();env.getPropertySources().addFirst(new org.springframework.core.env.MapPropertySource("TEST_ONLY",Map.of("pawday.erp-wms.simulation-enabled",true,"pawday.erp-wms.delivery-scenario",mode.startsWith("WRONG_")?"TEST_ACCEPTED":mode)));return new SyntheticOrderAdapter(new IntegrationPolicy(env),db);}
  public Observation query(Instruction i){queryCalls.incrementAndGet();if(i.businessKey().equals(blockKey)){blockKey=null;entered.countDown();try{assertTrue(release.await(15,TimeUnit.SECONDS));}catch(InterruptedException e){throw new AssertionError(e);}return new Observation("UNKNOWN",i.connection(),i.merchant(),i.businessKey(),i.payloadSha256(),null,false);}return delegate().query(i);}
  public Observation submit(Instruction i){submitCalls.incrementAndGet();submitsByKey.merge(i.businessKey(),1,Integer::sum);var o=delegate().submit(i);return switch(mode){case "WRONG_HASH"->new Observation(o.result(),o.connection(),o.merchant(),o.businessKey(),"f".repeat(64),o.reference(),false);case "WRONG_OWNER"->new Observation(o.result(),UUID.randomUUID(),o.merchant(),o.businessKey(),o.payloadSha256(),o.reference(),false);case "WRONG_KEY"->new Observation(o.result(),o.connection(),o.merchant(),"TEST_ONLY_WRONG",o.payloadSha256(),o.reference(),false);default->o;};}
 }
