 @Test void actualCollectionDeclaresOnceAndQueryBeforeSendFreezesNoPii(){var f=paid(2,List.of());UUID d=declare(f);assertEquals(d,declare(f));assertEquals("READY",ds(d));assertEquals(0,adapter.submitCalls.get());
  assertEquals(200,read(root(f),merchant).status());var r=retry(f,d);assertEquals(200,r.status(),r.body().toString());assertEquals("ACCEPTED",ds(d));assertFalse(r.data().get("responsibility_open").asBoolean());assertTrue(r.data().get("fulfillment_hold_open").asBoolean());assertEquals(1,adapter.queryCalls.get());assertEquals(1,adapter.submitCalls.get());
  assertEquals(1,db.queryForObject("SELECT count(*) FROM integration_delivery_fixture_orders WHERE business_key=?",Integer.class,r.data().get("business_key").asString()));assertEquals(18,balance(f.offer()));assertEquals(0,db.queryForObject("SELECT count(*) FROM integration_stock_acknowledgements WHERE connection_id=?",Integer.class,conn(f)));
  String frozen=db.queryForObject("SELECT frozen_payload::text FROM integration_order_deliveries WHERE id=?",String.class,d);for(String secret:List.of("TEST recipient","13800000000","TEST-only address","recipient","phone"))assertFalse(frozen.contains(secret),frozen);assertEquals(0,db.queryForObject("SELECT count(*) FROM shipments WHERE suborder_id=?",Integer.class,UUID.fromString(sub(f))));
 }
