 @Test void auditFailureRollsBackDeclarationAndClaimBeforeAnyIo(){var f=paid(1,List.of());db.execute("CREATE FUNCTION b2_fail_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action LIKE 'integration.delivery.%' THEN RAISE EXCEPTION 'TEST_ONLY_AUDIT_DOWN';END IF;RETURN NEW;END $$");db.execute("CREATE TRIGGER b2_fail_audit BEFORE INSERT ON audit_event FOR EACH ROW EXECUTE FUNCTION b2_fail_audit()");try{assertThrows(org.springframework.dao.DataAccessException.class,()->declare(f));assertEquals(0,db.queryForObject("SELECT count(*) FROM integration_order_deliveries WHERE suborder_id=?",Integer.class,UUID.fromString(sub(f))));}finally{db.execute("DROP TRIGGER b2_fail_audit ON audit_event");db.execute("DROP FUNCTION b2_fail_audit()");}UUID d=declare(f);
  db.execute("CREATE FUNCTION b2_fail_claim() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='integration.delivery.retry' THEN RAISE EXCEPTION 'TEST_ONLY_AUDIT_DOWN';END IF;RETURN NEW;END $$");db.execute("CREATE TRIGGER b2_fail_claim BEFORE INSERT ON audit_event FOR EACH ROW EXECUTE FUNCTION b2_fail_claim()");try{assertEquals(503,retry(f,d).status());assertEquals("READY",ds(d));assertEquals(0,adapter.submitCalls.get());}finally{db.execute("DROP TRIGGER b2_fail_claim ON audit_event");db.execute("DROP FUNCTION b2_fail_claim()");}assertEquals(200,retry(f,d).status());}
 @Test void everyHttpOperationCoversBadInputAuthenticationScopePermissionAndUnavailable(){var f=paid(1,List.of());UUID d=declare(f);String noPermission=identity("MERCHANT",merchantId,List.of("order.read"));
  for(String suffix:List.of("","/"+d+"/requery","/"+d+"/retry")){String path=root(f)+suffix,method=suffix.isEmpty()?"GET":"POST";Object body=suffix.endsWith("retry")?Map.of("reason_code","TEST_SCENARIO_RETRY"):suffix.isEmpty()?null:Map.of();var headers=Map.of("Idempotency-Key",key(),"If-Match","\"0\"","X-Reverify-Token",proofFor("integration.delivery.retry",merchant));
   assertEquals(400,req(method,path.replace(store.toString(),"bad-id"),body,merchant,headers).status());assertEquals(401,req(method,path,body,null,headers).status());assertEquals(403,req(method,path,body,noPermission,headers).status());assertEquals(404,req(method,path.replace(store.toString(),UUID.randomUUID().toString()),body,merchant,headers).status());assertEquals(404,req(method,path,body,foreign,headers).status());
   db.execute("ALTER TABLE integration_connections RENAME TO b2_connections_outage");try{assertEquals(503,req(method,path,body,merchant,headers).status());}finally{db.execute("ALTER TABLE b2_connections_outage RENAME TO integration_connections");}
  }
 }

